File=docs/receipts/hv/hv-ug-r8b-summarize.ps1; LineCount=46
1: <#
2: .SYNOPSIS
3: Summarizes captured review data without executing project code.
4: #>
5: [CmdletBinding()]
6: param([ValidateSet('Scope','Trx','Stores','Inventory')][string]$Mode)
7: $ErrorActionPreference='Stop'
8: switch($Mode){
9:     'Scope'{
10:         $scope=Get-Content -LiteralPath (Join-Path $PSScriptRoot 'hv-ug-r8b-scope.json') -Raw|ConvertFrom-Json -Depth 60
11:         foreach($label in @('head','base','docs-after-code','label-range','merge-d43c1d12','merge-parents','label-patch','merge-tree-read-only','cline-search','scanner-history')){
12:             $entry=$scope|Where-Object label -eq $label
13:             if($label -in @('docs-after-code','label-range','merge-d43c1d12')){
14:                 $lines=@($entry.output -split '\r?\n'|Where-Object{$_})
15:                 [pscustomobject]@{label=$label;exitCode=$entry.exitCode;lineCount=$lines.Count;nonDocs=@($lines|Where-Object{$_ -notmatch '^(?:[A-Z]\s+)?docs/'})}|ConvertTo-Json -Depth 10
16:             }else{[pscustomobject]@{label=$label;exitCode=$entry.exitCode;output=$entry.output}|ConvertTo-Json -Depth 10}
17:         }
18:         $changes=($scope|Where-Object label -eq 'review-changes').output -split '\r?\n'|Where-Object{$_ -and $_ -notmatch '^[A-Z]\s+docs/'}
19:         Write-Output 'Non-document changes:'
20:         $changes
21:         $history=($scope|Where-Object label -eq 'first-parent-history').output -split 'END-COMMIT'|Where-Object{$_ -match '\S'}
22:         [pscustomobject]@{firstParentCount=$history.Count;unsigned=@($history|Where-Object{$_ -notmatch 'Signed:.*Confidence:'});commits=@($history|ForEach-Object{($_ -split '\r?\n'|Where-Object{$_}|Select-Object -First 4)-join ' | '})}|ConvertTo-Json -Depth 10
23:     }
24:     'Trx'{
25:         $report=Get-Content -LiteralPath (Join-Path $PSScriptRoot 'hv-ug-r8b-trx-inspection.json') -Raw|ConvertFrom-Json -Depth 80
26:         $report.records|Where-Object{$null -ne $_.total -and (-not $_.countersMatch -or -not $_.timesMatch -or -not $_.allResultsPassed)}|Select-Object path,countersMatch,allResultsPassed,timesMatch,start,finish,total,resultCount|ConvertTo-Json -Depth 10
27:     }
28:     'Stores'{
29:         Import-Module powershell-yaml
30:         $items=[Collections.Generic.List[object]]::new()
31:         foreach($file in Get-ChildItem -LiteralPath $PSScriptRoot -Filter 'hv-ug-r8b-plugin-requirement-*.txt'){
32:             $parsed=Get-Content -LiteralPath $file.FullName -Raw|ConvertFrom-Yaml
33:             $items.Add([pscustomobject]@{path=$file.Name;payload=$parsed.payload})
34:         }
35:         [IO.File]::WriteAllText((Join-Path $PSScriptRoot 'hv-ug-r8b-requirements.json'),($items.ToArray()|ConvertTo-Json -Depth 100))
36:         foreach($item in $items){
37:             $payload=$item.payload
38:             [pscustomobject]@{path=$item.path;type=$payload.code;id=$payload.result.item.id;resultKeys=@($payload.result.Keys);error=$payload.message}|ConvertTo-Json -Compress
39:         }
40:     }
41:     'Inventory'{
42:         $paths=@(& rg --files 'docs/receipts/unit-suite-green-20261019' 'docs/receipts/hv' -g '*r8b*' -g '*r8-*' -g '*unitgreen-r7*' -g '*.meta.json')
43:         $paths|Where-Object{$_ -notmatch '\.trx$|\.response\.jsonl$|unitgreen-r8b-trx[/\\]|unitgreen-r8b-trx-a78640ba[/\\]'}
44:     }
45: }
46: Write-Output ('TimestampLocal='+(Get-Date -Format s))

