1: // FR-MCP-REPL-001: YAML Protocol STDIO REPL Host - Stream-level envelope loop
2: // FR-MCP-REPL-002: REPL Lifecycle Management - Read/accumulate/dispatch loop
3: // TR-MCP-REPL-003: Command Loop Lifecycle - Multi-line YAML framing
4: // TEST-MCP-REPL-001: REPL host processes well-formed multi-line YAML envelopes end-to-end
5: 
6: using System.Text;
7: 
8: namespace QBrainAi.Repl.Core;
9: 
10: /// <summary>
11: /// Runs the REPL agent-stdio read/write loop: reads envelope lines from a <see cref="TextReader"/>,
12: /// accumulates them into complete YAML documents (terminated by a blank line or the
13: /// <c>---</c> document separator), dispatches each via <see cref="IReplCommandDispatcher"/>,
14: /// and writes the response envelope back to the <see cref="TextWriter"/>.
15: /// </summary>
16: public interface IAgentStdioProtocol
17: {
18:     /// <summary>
19:     /// Runs the agent-stdio loop until the reader reports end-of-stream or cancellation.
20:     /// </summary>
21:     /// <param name="reader">Inbound envelope stream.</param>
22:     /// <param name="writer">Outbound response stream. The implementation flushes after each envelope.</param>
23:     /// <param name="cancellationToken">Cancellation token.</param>
24:     Task RunAsync(TextReader reader, TextWriter writer, CancellationToken cancellationToken);
25: }
26: 
27: /// <summary>
28: /// Default <see cref="IAgentStdioProtocol"/> implementation. Accumulates inbound lines into
29: /// YAML documents using the blank-line and <c>---</c> conventions, delegates parsing to
30: /// <see cref="IYamlSerializer"/>, and routes each envelope through
31: /// <see cref="IReplCommandDispatcher"/>. Malformed documents are reported as
32: /// <c>invalid_envelope</c> errors and the loop continues.
33: /// </summary>
34: public sealed class AgentStdioProtocol : IAgentStdioProtocol
35: {
36:     private const string CommandTimeoutEnvVar = "MCPSERVER_REPL_COMMAND_TIMEOUT_SECONDS";
37: 
38:     private readonly IYamlSerializer _serializer;
39:     private readonly IReplCommandDispatcher _dispatcher;
40: 
41:     /// <summary>
42:     /// Initializes a new <see cref="AgentStdioProtocol"/>.
43:     /// </summary>
44:     /// <param name="serializer">YAML serializer used to parse and emit envelopes.</param>
45:     /// <param name="dispatcher">Command dispatcher invoked once per complete inbound envelope.</param>
46:     public AgentStdioProtocol(IYamlSerializer serializer, IReplCommandDispatcher dispatcher)
