File=tests/QBrainAi.Repl.Core.Tests/ReplCommandTimeoutCallSiteTests.cs; LineCount=344
202:     /// Binding: the agent stdio protocol, given the scripted reader through its <c>ReadVariable</c> seam and a
203:     /// dispatcher whose command answers at once or runs until cancelled, satisfies the same contract rows the scripted
204:     /// reference passed and the wrong call sites failed. The two timeout rows wait 1 and 2 seconds of real time.
205:     /// </summary>
206:     [Fact]
207:     public async Task ProductionProtocol_SatisfiesTheContract() =>
208:         await AssertCallSiteContract(CommandVariable, StreamVariable, CommandMessageFormat, RunProtocolAsync).ConfigureAwait(true);
209: 
210:     /// <summary>
211:     /// Binding: a TODO stream command (workflow.todo.streamStatus) through the dispatcher, given the scripted reader
212:     /// through its <c>ReadVariable</c> seam and a workflow whose stream ends at once or runs until cancelled, satisfies
213:     /// the same contract rows. The two timeout rows wait 1 and 2 seconds of real time.
214:     /// </summary>
215:     [Fact]
216:     public async Task ProductionStreamCommand_SatisfiesTheContract() =>
217:         await AssertCallSiteContract(StreamVariable, CommandVariable, StreamMessageFormat, RunStreamCommandAsync).ConfigureAwait(true);
218: 
219:     private static async Task<CallSiteResult> RunProtocolAsync(Func<string, string?> read, bool runsUntilCancelled)
220:     {
221:         var serializer = new YamlSerializer();
222:         var sut = new AgentStdioProtocol(serializer, new ScriptedDispatcher(runsUntilCancelled)) { ReadVariable = read };
223:         var input = new StringBuilder()
224:             .AppendLine("type: request")
225:             .AppendLine("payload:")
226:             .AppendLine("  requestId: req-callsite-timeout")
227:             .AppendLine("  method: client.todo.QueryAsync")
228:             .AppendLine()
229:             .ToString();
230:         using var reader = new StringReader(input);
231:         using var writer = new StringWriter();
232:         await sut.RunAsync(reader, writer, TestContext.Current.CancellationToken).ConfigureAwait(true);
233: 
234:         var response = serializer.Deserialize(FirstDocument(writer.ToString()));
235:         return response.Payload switch
236:         {
237:             ErrorPayload { Code: "command_timeout" } error => new CallSiteResult(TimedOut, error.Message),
238:             ErrorPayload error => new CallSiteResult("error " + error.Code, error.Message),
239:             ResultPayload => new CallSiteResult(Completed, null),
240:             _ => new CallSiteResult("envelope " + response.Type, null),
241:         };
242:     }
243: 
244:     private static async Task<CallSiteResult> RunStreamCommandAsync(Func<string, string?> read, bool runsUntilCancelled)
245:     {
246:         var todo = Substitute.For<ITodoWorkflow>();
247:         todo.StreamStatusAsync("MCP-TIMEOUT-001", Arg.Any<Func<IStreamingEvent, Task>>(), Arg.Any<CancellationToken>())
248:             .Returns(call => runsUntilCancelled
249:                 ? Task.Delay(Timeout.Infinite, call.ArgAt<CancellationToken>(2))
250:                 : Task.CompletedTask);
251:         var sut = new ReplCommandDispatcher(Substitute.For<IGenericClientPassthrough>(), todoWorkflow: todo) { ReadVariable = read };
252:         var envelope = new YamlEnvelope
253:         {
254:             Type = "request",
255:             Payload = new RequestPayload
256:             {
257:                 RequestId = "req-callsite-stream",
258:                 Method = TodoCommandShapes.StreamStatusMethod,
259:                 Params = new Dictionary<string, object?> { ["id"] = "MCP-TIMEOUT-001" },
260:             },
261:         };
262: 
263:         var response = await sut.DispatchAsync(envelope, TestContext.Current.CancellationToken).ConfigureAwait(true);
264:         if (response.Payload is ErrorPayload error)
265:         {
266:             return new CallSiteResult("error " + error.Code, error.Message);
267:         }
268: 
269:         if (response.Payload is not ResultPayload { Result: IReadOnlyList<IStreamingEvent> events })
270:         {
271:             return new CallSiteResult("envelope " + response.Type, null);
272:         }
273: 
274:         var timeout = events.LastOrDefault(evt => evt.EventType == "stream.timeout");
275:         return timeout is null
276:             ? new CallSiteResult(Completed, null)
277:             : new CallSiteResult(TimedOut, (timeout.Data as IReadOnlyDictionary<string, object?>)?.GetValueOrDefault("message") as string);
278:     }
279: 
280:     /// <summary>The first YAML document of the protocol's output, which frames each envelope with a "---" line.</summary>
281:     private static string FirstDocument(string output)
282:     {
283:         var document = new StringBuilder();
284:         foreach (var line in output.Replace("\r\n", "\n", StringComparison.Ordinal).Split('\n'))
285:         {
286:             if (line.Trim() == "---")
287:             {
288:                 if (document.Length == 0)
289:                 {
290:                     continue;
291:                 }
292: 
293:                 break;
294:             }
295: 
296:             document.AppendLine(line);
297:         }
298: 
299:         return document.ToString();
300:     }
301: 
302:     /// <summary>A dispatcher whose one command answers at once, or runs until its token is cancelled.</summary>
303:     private sealed class ScriptedDispatcher(bool runsUntilCancelled) : IReplCommandDispatcher
304:     {
305:         public async Task<IYamlEnvelope> DispatchAsync(IYamlEnvelope envelope, CancellationToken cancellationToken)
306:         {
307:             if (runsUntilCancelled)
308:             {
309:                 await Task.Delay(Timeout.Infinite, cancellationToken).ConfigureAwait(true);
310:             }
311: 
312:             return new YamlEnvelope
313:             {
314:                 Type = "result",
315:                 Payload = new ResultPayload { RequestId = "req-callsite-timeout", Result = "answered" },
316:             };
317:         }
318:     }
319: 
320:     /// <summary>
321:     /// A scripted call site: reads <paramref name="variable"/> once, parses it with <paramref name="parse"/>, arms the
322:     /// runtime's cancellation timer with the result (which throws for an out-of-range delay, as the real timer does), and
323:     /// reports a timeout naming the applied seconds for a command that runs until cancelled.
324:     /// </summary>
325:     private static Task<CallSiteResult> ScriptedCallSite(
326:         Func<string, string?> read,
327:         bool runsUntilCancelled,
328:         string variable,
329:         string messageFormat,
330:         Func<string?, TimeSpan> parse)
331:     {
332:         var timeout = parse(read(variable));
333:         using var timer = new CancellationTokenSource();
334:         timer.CancelAfter(timeout);
335:         return Task.FromResult(runsUntilCancelled
336:             ? new CallSiteResult(TimedOut, string.Format(CultureInfo.InvariantCulture, messageFormat, timeout.TotalSeconds))
337:             : new CallSiteResult(Completed, null));
338:     }
339: 
340:     private static CallSiteResult WithMessage(CallSiteResult result, string messageFormat, long seconds) =>
341:         result.Kind == TimedOut
342:             ? result with { Message = string.Format(CultureInfo.InvariantCulture, messageFormat, seconds) }
343:             : result;
344: }

