11: /// </summary>
12: public sealed class OllamaServerFixture : IAsyncLifetime
13: {
14:     private const string TagsEndpoint = "http://localhost:11434/api/tags";
15:     private static readonly TimeSpan ProbeTimeout = TimeSpan.FromSeconds(5);
16:     private static readonly TimeSpan PollInterval = TimeSpan.FromSeconds(1);
17:     private static readonly TimeSpan StartupTimeout = TimeSpan.FromSeconds(60);
18: 
