21:     /// <summary>Initializes the fixture with the real probe, executable resolver, and process launcher.</summary>
22:     public OllamaServerFixture()
23:         => _controller = new OllamaServerController(
24:             probeAsync: ProbeAsync,
25:             resolveExecutable: ResolveExecutable,
26:             startProcess: StartServerProcess,
27:             pollInterval: PollInterval,
28:             startupTimeout: StartupTimeout);
29: 
30:     /// <summary>Gets a value indicating whether this fixture launched the server it is using.</summary>
31:     public bool StartedByFixture => _controller.LastResult?.StartedByController ?? false;
32: 
33:     /// <inheritdoc />
34:     public async ValueTask InitializeAsync()
35:         => await _controller.EnsureRunningAsync(CancellationToken.None).ConfigureAwait(false);
36: 
