41:     private static async Task<bool> ProbeAsync(CancellationToken cancellationToken)
42:     {
43:         using var client = new HttpClient { Timeout = ProbeTimeout };
44:         try
45:         {
46:             using var response = await client.GetAsync(new Uri(TagsEndpoint), cancellationToken).ConfigureAwait(false);
47:             return response.IsSuccessStatusCode;
48:         }
49:         catch (Exception ex) when (ex is HttpRequestException or TaskCanceledException)
50:         {
51:             return false;
52:         }
53:     }
54: 
55:     private static string? ResolveExecutable()
56:     {
57:         var candidates = new List<string>();
58: 
59:         var pathVariable = Environment.GetEnvironmentVariable("PATH") ?? string.Empty;
60:         foreach (var directory in pathVariable.Split(Path.PathSeparator, StringSplitOptions.RemoveEmptyEntries))
61:         {
62:             try
63:             {
64:                 candidates.Add(Path.Combine(directory.Trim(), OperatingSystem.IsWindows() ? "ollama.exe" : "ollama"));
65:             }
66:             catch (ArgumentException)
67:             {
68:                 // Ignore malformed PATH entries rather than failing discovery.
69:             }
70:         }
71: 
72:         var localAppData = Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData);
73:         candidates.Add(Path.Combine(localAppData, "Programs", "Ollama", "ollama.exe"));
74:         // Matches the portable install locations used by the InstallOllama Nuke target (TR-MCP-NUKE-019):
75:         // the Windows zip puts the executable at the folder root, the Linux tarball under bin/.
76:         candidates.Add(Path.Combine(localAppData, "QBrainAi", "test-tools", "ollama", "ollama.exe"));
77:         candidates.Add(Path.Combine(localAppData, "QBrainAi", "test-tools", "ollama", "bin", "ollama"));
78: 
79:         return candidates.FirstOrDefault(File.Exists);
80:     }
