10: /// <summary>
11: /// Creates a Windows directory junction with operating-system calls made in the test process: the alias folder is
12: /// created, opened as a reparse point (CreateFileW) and given a mount-point reparse buffer
13: /// (DeviceIoControl FSCTL_SET_REPARSE_POINT), so a fixture never depends on how long a helper process takes to start
14: /// (TR-MCP-USECASE-019 AC-008 as replaced 2026-10-26T14:18:23; operator: "Fix flake, strengthen AC (Recommended)";
15: /// triage-report-8c2c30ef63d442bdb29fd785ec91e7d7).
16: /// </summary>
17: internal static class WindowsJunction
18: {
19:     /// <summary>IO_REPARSE_TAG_MOUNT_POINT, the reparse tag of a directory junction.</summary>
20:     internal const uint MountPointTag = 0xA0000003;
21: 
22:     private const uint SetReparsePointControl = 0x000900A4;
23:     private const uint GenericWrite = 0x40000000;
24:     private const uint OpenExisting = 3;
25:     private const uint FlagOpenReparsePoint = 0x00200000;
26:     private const uint FlagBackupSemantics = 0x02000000;
27: 
28:     /// <summary>
29:     /// Builds the mount-point REPARSE_DATA_BUFFER for <paramref name="targetFullPath"/>: the tag, the data length,
30:     /// a reserved field, the substitute and print name offsets and lengths, then the UTF-16 substitute name "\??\"
31:     /// plus the target, a null, the print name (the target) and a null.
32:     /// </summary>
33:     /// <param name="targetFullPath">The absolute target folder.</param>
34:     /// <returns>The buffer bytes.</returns>
35:     internal static byte[] BuildMountPointBuffer(string targetFullPath)
36:     {
37:         ArgumentException.ThrowIfNullOrEmpty(targetFullPath);
38:         var substitute = Encoding.Unicode.GetBytes(@"\??\" + targetFullPath);
39:         var print = Encoding.Unicode.GetBytes(targetFullPath);
40:         var pathLength = substitute.Length + 2 + print.Length + 2;
41:         var buffer = new byte[16 + pathLength];
42:         BinaryPrimitives.WriteUInt32LittleEndian(buffer.AsSpan(0, 4), MountPointTag);
43:         BinaryPrimitives.WriteUInt16LittleEndian(buffer.AsSpan(4, 2), checked((ushort)(8 + pathLength)));
44:         BinaryPrimitives.WriteUInt16LittleEndian(buffer.AsSpan(10, 2), checked((ushort)substitute.Length));
45:         BinaryPrimitives.WriteUInt16LittleEndian(buffer.AsSpan(12, 2), checked((ushort)(substitute.Length + 2)));
46:         BinaryPrimitives.WriteUInt16LittleEndian(buffer.AsSpan(14, 2), checked((ushort)print.Length));
47:         substitute.CopyTo(buffer, 16);
48:         print.CopyTo(buffer, 16 + substitute.Length + 2);
49:         return buffer;
50:     }
51: 
52:     /// <summary>
53:     /// Creates the junction <paramref name="aliasPath"/> that points at <paramref name="targetPath"/>; the alias folder
54:     /// must not exist. On failure the alias folder is removed and a <see cref="Win32Exception"/> is thrown.
55:     /// </summary>
56:     /// <param name="aliasPath">The junction to create.</param>
57:     /// <param name="targetPath">The existing folder it points at.</param>
58:     [SupportedOSPlatform("windows")]
59:     internal static void Create(string aliasPath, string targetPath)
60:     {
61:         ArgumentException.ThrowIfNullOrEmpty(aliasPath);
62:         ArgumentException.ThrowIfNullOrEmpty(targetPath);
63:         var buffer = BuildMountPointBuffer(Path.GetFullPath(targetPath));
64:         Directory.CreateDirectory(aliasPath);
65:         try
66:         {
67:             using var handle = CreateFile(aliasPath, GenericWrite, 0, IntPtr.Zero, OpenExisting, FlagOpenReparsePoint | FlagBackupSemantics, IntPtr.Zero);
68:             if (handle.IsInvalid)
69:                 throw new Win32Exception(Marshal.GetLastWin32Error(), $"Opening {aliasPath} as a reparse point failed.");
70:             if (!DeviceIoControl(handle, SetReparsePointControl, buffer, (uint)buffer.Length, IntPtr.Zero, 0, out _, IntPtr.Zero))
71:                 throw new Win32Exception(Marshal.GetLastWin32Error(), $"Setting the junction reparse point on {aliasPath} failed.");
72:         }
73:         catch
74:         {
75:             Directory.Delete(aliasPath);
76:             throw;
77:         }
78:     }
79: 
80:     [DllImport(
81:         "kernel32.dll",
82:         EntryPoint = "CreateFileW",
83:         CharSet = CharSet.Unicode,
84:         SetLastError = true)]
85:     private static extern SafeFileHandle CreateFile(
86:         string fileName,
87:         uint desiredAccess,
88:         uint shareMode,
89:         IntPtr securityAttributes,
90:         uint creationDisposition,
91:         uint flagsAndAttributes,
92:         IntPtr templateFile);
93: 
94:     [DllImport("kernel32.dll", SetLastError = true)]
95:     [return: MarshalAs(UnmanagedType.Bool)]
96:     private static extern bool DeviceIoControl(
97:         SafeFileHandle device,
98:         uint controlCode,
99:         byte[] inBuffer,
100:         uint inBufferSize,
101:         IntPtr outBuffer,
102:         uint outBufferSize,
103:         out uint bytesReturned,
104:         IntPtr overlapped);
105: }

