27:     /// before the root, and one that reports the searched folders in reverse.
28:     /// </summary>
29:     /// <param name="fault">Injected fault.</param>
30:     [Theory]
31:     [InlineData(WalkFault.StartOnly)]
32:     [InlineData(WalkFault.SkipsStart)]
33:     [InlineData(WalkFault.FarthestWins)]
34:     [InlineData(WalkFault.StopsBeforeRoot)]
35:     [InlineData(WalkFault.ReversedOrder)]
