42:     /// </summary>
43:     /// <param name="fault">Injected fault.</param>
44:     [Theory]
45:     [InlineData(DiagnosisFault.OmitsSearchedFolders)]
46:     [InlineData(DiagnosisFault.OmitsMarkerName)]
47:     [InlineData(DiagnosisFault.ReportsSuccess)]
48:     public void WrongDiagnosis_IsRejected(DiagnosisFault fault)
49:         => Assert.ThrowsAny<XunitException>(
