18: {
19:     private static readonly StringComparison s_pathComparison =
20:         OperatingSystem.IsWindows() ? StringComparison.OrdinalIgnoreCase : StringComparison.Ordinal;
21: 
22:     private static readonly EnumerationOptions s_singleLevel = new()
23:     {
24:         RecurseSubdirectories = false,
25:         IgnoreInaccessible = false,
26:         AttributesToSkip = 0,
27:         ReturnSpecialDirectories = false,
28:     };
29: 
30:     private readonly Func<string, IReadOnlyList<DirectoryListingEntry>> _list;
31: 
32:     /// <summary>Creates a walker that lists each directory through <paramref name="list"/>.</summary>
