52: 
53:     /// <summary>
54:     /// AC-TR-MCP-WS-005-001, AC-TR-MCP-SESSIONLOG-006-009: whether <paramref name="root"/> may be walked from
55:     /// <paramref name="boundary"/>: the root and every folder between the boundary and it must each be listed by
56:     /// its parent as a directory that is not a link or other reparse point. The boundary itself is trusted (a user
57:     /// profile or home that is itself a link is still scanned) and its parent is never listed; a root that is the
58:     /// boundary is reachable without any listing.
59:     /// </summary>
60:     /// <remarks>
61:     /// A folder whose listing fails with an <see cref="IOException"/> or <see cref="UnauthorizedAccessException"/>
62:     /// cannot be traversed, so the root is not reachable; any other listing error propagates. A root that is not
63:     /// below the boundary, or that a parent does not list as a directory, is not reachable.
64:     /// </remarks>
65:     /// <param name="boundary">The trusted folder the scan starts from (the user profile or home).</param>
66:     /// <param name="root">The scan root below <paramref name="boundary"/>.</param>
67:     /// <returns>True when the root may be walked.</returns>
68:     internal bool IsReachable(string boundary, string root)
69:     {
70:         ArgumentNullException.ThrowIfNull(boundary);
71:         ArgumentNullException.ThrowIfNull(root);
72:         var target = Path.TrimEndingDirectorySeparator(root);
73:         var current = Path.TrimEndingDirectorySeparator(boundary);
74:         while (!string.Equals(current, target, s_pathComparison))
75:         {
76:             IReadOnlyList<DirectoryListingEntry> entries;
77:             try
78:             {
79:                 entries = _list(current);
80:             }
81:             catch (IOException)
82:             {
83:                 return false;
84:             }
85:             catch (UnauthorizedAccessException)
86:             {
87:                 return false;
88:             }
89: 
90:             var found = entries
91:                 .Where(entry => LeadsTo(entry.Path, target))
92:                 .Select(entry => (DirectoryListingEntry?)entry)
93:                 .FirstOrDefault();
94:             if (found is not { } next || !next.IsDirectory || next.IsLink || next.Path.Length <= current.Length)
95:                 return false;
96:             current = next.Path;
97:         }
98: 
99:         return true;
100:     }
101: 
102:     /// <summary>True when <paramref name="path"/> is <paramref name="target"/> or a folder above it.</summary>
103:     private static bool LeadsTo(string path, string target) =>
104:         target.StartsWith(path, s_pathComparison)
105:         && (target.Length == path.Length
106:             || target[path.Length] == Path.DirectorySeparatorChar
107:             || target[path.Length] == Path.AltDirectorySeparatorChar);
108: 
109:     /// <summary>Lists one real directory with each entry's directory and link flags.</summary>
110:     /// <param name="directory">Directory to list.</param>
111:     /// <returns>The entries of <paramref name="directory"/>.</returns>
112:     internal static IReadOnlyList<DirectoryListingEntry> ListFileSystem(string directory) =>
113:         new DirectoryInfo(directory)
114:             .EnumerateFileSystemInfos("*", s_singleLevel)
115:             .Select(info => new DirectoryListingEntry(
116:                 info.FullName,
117:                 info is DirectoryInfo,
118:                 (info.Attributes & FileAttributes.ReparsePoint) != 0))
119:             .ToList();
120: 
121:     private IEnumerable<string> Walk(string root, bool yieldDirectories)
122:     {
123:         var pending = new Queue<string>();
124:         pending.Enqueue(root);
125:         while (pending.Count > 0)
126:         {
127:             foreach (var entry in TryList(pending.Dequeue()))
128:             {
129:                 if (entry.IsDirectory)
130:                 {
131:                     if (entry.IsLink)
132:                         continue;
133:                     pending.Enqueue(entry.Path);
134:                     if (yieldDirectories)
135:                         yield return entry.Path;
136:                 }
137:                 else if (!yieldDirectories)
138:                 {
139:                     yield return entry.Path;
140:                 }
141:             }
142:         }
143:     }
144: 
145:     private IReadOnlyList<DirectoryListingEntry> TryList(string directory)
146:     {
147:         try
148:         {
149:             return _list(directory);
150:         }
151:         catch (IOException)
152:         {
153:             return [];
154:         }
155:         catch (UnauthorizedAccessException)
156:         {
157:             return [];
158:         }
159:     }
160: }

